line.style.strokeDashoffset = lineLen;

function frame(t, p, d) {
  const s = 0.55;
  const pt = clamp(p / s);

  // Header entry
  const hS = spr(t, 0, 0.8, 6);
  head.style.opacity = hS;
  head.style.transform = `translateY(${lerp(20, 0, hS)}px)`;

  // Line progress
  const lp = E_INOUT(clamp(pt * 1.1));
  line.style.strokeDashoffset = lineLen * (1 - lp);

  cards.forEach((el, i) => {
    const start = 0.1 + (i * 0.1);
    const end = start + 0.15;
    // Spring entry
    const spring = spr(t, start * d, 0.85, 8);
    const yOff = lerp(40, 0, spring);

    el.style.opacity = spring;
    el.style.transform = `translateY(${yOff}px) scale(${lerp(0.9, 1, spring)})`;

    // Contrast check: Ensure the labels are sharp only when they arrive
    if (p > start && p < s) {
        const pulse = Math.sin(clamp((p - start) / (end - start)) * Math.PI) * 0.03;
        el.style.transform += ` scale(${1 + pulse})`;
    }
  });

  // Final static state
  if (p >= s) {
    head.style.opacity = 1;
    line.style.strokeDashoffset = 0;
    cards.forEach(el => {
      el.style.opacity = 1;
      el.style.transform = 'translateY(0px) scale(1)';
    });
  }
}
